use mgbfs_runtime::generic_distributed_memory::GenericDistributedMemoryPlan as P;
#[test]fn large_vram_is_not_capped_at_2pow28(){for world in [1,8,128]{for bytes in [160u64<<30,180u64<<30]{let p=P::automatic_storage_history(14,world,32,3,1024,bytes,None,1,3).unwrap();assert!(p.capacity>1<<28,"{p:?}");assert!(p.table_slots>u64::from(u32::MAX));assert!(p.device_bytes<=bytes-bytes/10);p.validate(3).unwrap();let larger=P::with_storage_history(14,world,32,p.capacity+1,p.batch,3,1024,1,3).unwrap();assert!(larger.device_bytes>bytes-bytes/10);}}}
#[test]fn rolling_full_u32_row_range_is_checked(){let p=P::with_storage_history(1,1,1,(u32::MAX-3)/3,1,1,1,1,3).unwrap();assert!(u64::from(p.capacity)*3>1u64<<31);assert!(P::with_storage_history(1,1,1,(u32::MAX-3)/3+1,1,1,1,1,3).is_err());}
#[test]fn physical_memory_limits_small_and_wide_states(){for width in [14,64]{for bytes in [1,8]{let p=P::automatic_storage_history(width,2,32,3,1024,12u64<<30,None,bytes,3).unwrap();assert!(p.device_bytes<=(12u64<<30)*9/10);p.validate(3).unwrap();}}}
